        CREATE OR REPLACE FUNCTION seed_test_orders() RETURNS void AS $$
DECLARE
        u RECORD;
  num_orders INT;
  i INT;
        BEGIN
        FOR u IN SELECT id, username FROM users LOOP
            num_orders := floor(random() * 6)::int;
        FOR i IN 1..num_orders LOOP
      INSERT INTO orders(id, user_id, description, status, created_at)
      VALUES (
        gen_random_uuid(),
        u.id,
        concat('Order ', i, ' for ', u.username),
        'CREATED',
        NOW()
      );
        END LOOP;
        END LOOP;
        END;
$$ LANGUAGE plpgsql;

        SELECT seed_test_orders();

        DROP FUNCTION IF EXISTS seed_test_orders();
